def f_union(g):
    o=[r[:] for r in g]; h,w=len(g),len(g[0]); bg=g[0][0]
    # group rows into objects via connectivity on non-bg
    seen=set(); groups=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; grp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); grp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and g[na][nb]==g[a][b] and (na,nb) not in seen: st.append((na,nb))
                groups.append(grp)
    for grp in groups:
        mi=min(a for a,b in grp); ma=max(a for a,b in grp)
        mj=min(b for a,b in grp); Mk=max(b for a,b in grp)
        for a in range(mi,ma+1):
            for b in range(mj,Mk+1):
                if g[a][b]==bg: o[a][b]=1
        # trailing extension to grid edge
        for a in range(mi,ma+1):
            for b in range(Mk+1,w): o[a][b]=1
    return o
